import assert from 'node:assert/strict';
import { find, visible, selector, dispatchNativeClick } from './native-ui.mjs';
import { decodeRecommendation, decodeReadPage, decodeRecommendationSummary, decodeRecommendationOption,
  decodeRecommendationDecision, decodeHearingPack, decodeHearingPackItem } from './client-extensions-contract.mjs';
import { parseClientCompatibility } from './client-extensions-contract.mjs';
import { clientExtensionInventory, collectClientExtensions } from './client-extensions-inventory.mjs';
import { ClientExtensionUnavailable, record, tap, textTap, waitId, text, absent, privateAbsent,
  owner, authoritative, files, account, signOut, cameraPrivacy, runOsRecipe, background, cold, biometric,
  recordLink, openPending, locked, unlock, enableLock, inputNote, observedFact } from './client-extensions-ui.mjs';

const copy=v=>structuredClone(v);
async function noPost(c,before){const after=await c.controls.traffic();assert.equal(after.runId,before.runId);assert.deepEqual(after.requests.slice(0,before.requests.length),before.requests);assert.equal(after.requests.slice(before.requests.length).filter(x=>x.method==='POST').length,0,'CX_UNEXPECTED_NATIVE_POST');return after;}
async function captured(c){await tap(c,'files-camera');await runOsRecipe(c,'cameraCapture');await waitId(c,'files-selection');const observed=await cameraPrivacy(c,{empty:false});assert.equal(observed.counts.copies,1);assert.equal(observed.copies.length,1);assert.ok(observed.copies[0].sizeBytes>0);const names=c.fixture.cx.camera.filenames;assert.ok(Array.isArray(names)&&names.length===3);let matched=0;for(const name of names)if(await visible(c.driver,selector(c.platform,'text',name)))matched++;assert.equal(matched,1,'CX_ONE_NATIVE_CAPTURE_FILENAME_REQUIRED');return observed.copies[0];}
async function clear(c){await tap(c,'files-selection-clear');await absent(c,'files-selection');await cameraPrivacy(c);}
async function readthrough(c,kind,args={}){return authoritative(c,'readReadthrough',{kind,matterId:c.fixture.cx.readthrough.matterId,...args});}
async function recommendations(c){await c.openMatter(c.fixture.cx.readthrough.matter);await tap(c,'matter-recommendations');await waitId(c,'screen-readthrough');await waitId(c,'readthrough-read-only');}
async function recommendation(c,expected){await tap(c,'recommendation-'+expected.id);await waitId(c,'recommendation-body-'+expected.id,expected.record.title);for(const value of [expected.id,expected.updated_at,expected.record.rationale,...expected.record.retrieved_authorities])await text(c,value);}
async function currentNativeSession(c){const value=await authoritative(c,'readNativeSessionIdentity');assert.equal(value.observed,true);for(const key of ['userId','companyId','membershipId'])assert.equal(value[key],c.fixture.cx.identity[key]);assert.ok(typeof value.sessionId==='string'&&value.sessionId);return value;}
async function policy(c,phase){const value=await owner(c,'policyCheckpoint',{phase});assert.equal(value.observed,true);assert.equal(value.operation,phase);assert.equal(value.configurationReplayed,false);assert.equal(value.originalLedgerPreserved,true);assert.equal(value.databaseAndSecurityIdentityPreserved,true);assert.notEqual(value.receiptEvidence.sha256,value.previousReceiptEvidence.sha256);return value;}
async function policyValue(c){const r=await authoritative(c,'readCompatibility');return parseClientCompatibility(r.value,{platform:c.platform,version:c.fixture.cx.version.actual});}
function expectedRead(c,suffix){const matches=c.fixture.cx.readthrough.expectedReadbacks.filter(x=>x.route.endsWith(suffix));assert.equal(matches.length,1,'CX_COMPLETE_PRODUCER_READBACK_REQUIRED');return matches[0].value;}
async function noReadMutations(c,action){const before=await c.controls.traffic();await action();const after=await noPost(c,before);const rows=after.requests.slice(before.requests.length);assert.ok(rows.every(x=>x.method==='GET'||x.method==='OPTIONS'),'CX_READTHROUGH_NOT_GET_ONLY');}

